const translateCityName = async (cityName) => {
  const endpoint = 'https://libretranslate.de/translate';
  try {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        q: cityName,
        source: 'ko',
        target: 'en',
      }),
    });
    const data = await response.json();
    return data.translatedText; // 번역된 도시명 반환
  } catch (error) {
    console.error('번역 오류:', error);
    return cityName; // 번역 실패 시 원래 도시명 반환
  }
};

const fetchWeather = async () => {
  if (!city) {
    alert('도시 이름을 입력하세요.');
    return;
  }

  // 비동기적으로 도시명 번역
  const translatedCity = await translateCityName(city);
  console.log('번역된 도시명:', translatedCity);

  try {
    const response = await fetch(
      `https://api.openweathermap.org/data/2.5/weather?q=${translatedCity}&appid=${API_KEY}&units=metric&lang=kr`
    );
    const data = await response.json();
    console.log(data); // 데이터를 콘솔에 출력
    if (data.cod === 200) {
      setWeatherData(data); // 날씨 데이터 업데이트
    } else {
      alert('도시를 찾을 수 없습니다!');
      setWeatherData(null);
    }
  } catch (error) {
    console.error('날씨 데이터를 가져오는 중 오류가 발생했습니다:', error);
  }
};
